import { Component, OnInit, OnDestroy } from '@angular/core';
import { TaskService } from '../services/task-services';
import { AuthService } from '../services/auth.service';

interface TaskItem {
  id: string;
  title: string;
  category: string;
  priority: string;
  status: string;
  estimated_time: number;
  due_date: string;
  created_at: string;
  // UI state
  _loading?: boolean;
  _elapsed?: number;
  _timerRef?: any;
}

@Component({
  selector: 'app-task',
  templateUrl: './task.html',
  styleUrls: ['./task.css']
})
export class TaskComponent implements OnInit, OnDestroy {

  tasks: TaskItem[] = [];
  pageLoading = true;

  // Modal state
  modalOpen = false;
  modalTask: TaskItem | null = null;
  focusScore = 3;
  distractionCount = 0;
  modalLoading = false;
  modalError = '';

  // Toast
  toast: { type: 'success' | 'error'; message: string } | null = null;
  private toastTimer: any;

  // Filter
  filter: 'All' | 'Pending' | 'In Progress' | 'Completed' = 'All';

  constructor(private taskService: TaskService, private auth: AuthService) {}

  ngOnInit() { this.loadTasks(); }

  ngOnDestroy() {
    this.tasks.forEach(t => { if (t._timerRef) clearInterval(t._timerRef); });
  }

  get userId(): string { return this.auth.getUser()?.id ?? ''; }

  get filteredTasks(): TaskItem[] {
    return this.filter === 'All' ? this.tasks : this.tasks.filter(t => t.status === this.filter);
  }

  get counts() {
    return {
      all: this.tasks.length,
      pending: this.tasks.filter(t => t.status === 'Pending').length,
      inProgress: this.tasks.filter(t => t.status === 'In Progress').length,
      completed: this.tasks.filter(t => t.status === 'Completed').length,
    };
  }

  loadTasks() {
    this.pageLoading = true;
    this.taskService.getTasks().subscribe({
      next: (data) => {
        this.tasks = (data as TaskItem[]).map(t => ({ ...t, _loading: false, _elapsed: 0 }));
        this.pageLoading = false;
      },
      error: () => {
        this.pageLoading = false;
        this.showToast('error', '❌ Failed to load tasks');
      }
    });
  }

  startTask(task: TaskItem) {
    task._loading = true;
    this.taskService.startTask(task.id, this.userId).subscribe({
      next: () => {
        task.status = 'In Progress';
        task._loading = false;
        task._elapsed = 0;
        task._timerRef = setInterval(() => task._elapsed = (task._elapsed ?? 0) + 1, 1000);
        this.showToast('success', `▶️ "${task.title}" started`);
      },
      error: (err) => {
        task._loading = false;
        this.showToast('error', '❌ ' + (err?.error?.detail ?? 'Failed to start task'));
      }
    });
  }

  openModal(task: TaskItem) {
    this.modalTask = task;
    this.focusScore = 3;
    this.distractionCount = 0;
    this.modalError = '';
    this.modalOpen = true;
  }

  closeModal() {
    this.modalOpen = false;
    this.modalTask = null;
    this.modalLoading = false;
    this.modalError = '';
  }

  submitComplete() {
    if (!this.modalTask) return;
    if (this.distractionCount < 0) { this.modalError = 'Distraction count cannot be negative.'; return; }

    this.modalLoading = true;
    this.modalError = '';

    const payload = {
      focus_score: this.focusScore,
      distraction_count: this.distractionCount,
      user_id: this.userId
    };

    this.taskService.completeTask(this.modalTask.id, payload).subscribe({
      next: () => {
        const t = this.tasks.find(x => x.id === this.modalTask!.id);
        if (t) {
          t.status = 'Completed';
          if (t._timerRef) { clearInterval(t._timerRef); t._timerRef = null; }
        }
        this.showToast('success', `✅ "${this.modalTask!.title}" completed!`);
        this.closeModal();
      },
      error: (err) => {
        this.modalLoading = false;
        this.modalError = err?.error?.detail ?? 'Failed to complete task.';
      }
    });
  }

  formatElapsed(secs: number = 0): string {
    const m = Math.floor(secs / 60).toString().padStart(2, '0');
    const s = (secs % 60).toString().padStart(2, '0');
    return `${m}:${s}`;
  }

  priorityClass(p: string) {
    return p === 'High' ? 'p-high' : p === 'Medium' ? 'p-med' : 'p-low';
  }

  statusClass(s: string) {
    return s === 'Completed' ? 's-done' : s === 'In Progress' ? 's-progress' : 's-pending';
  }

  private showToast(type: 'success' | 'error', message: string) {
    clearTimeout(this.toastTimer);
    this.toast = { type, message };
    this.toastTimer = setTimeout(() => this.toast = null, 4000);
  }
}
<!-- Toast -->
<div class="toast" *ngIf="toast" [class.toast-success]="toast.type==='success'" [class.toast-error]="toast.type==='error'">
  {{ toast.message }}
</div>

<!-- Complete Modal -->
<div class="modal-backdrop" *ngIf="modalOpen" (click)="closeModal()">
  <div class="modal" (click)="$event.stopPropagation()">

    <div class="modal-header">
      <div class="modal-icon">✅</div>
      <div>
        <h3 class="modal-title">Complete Task</h3>
        <p class="modal-sub">{{ modalTask?.title }}</p>
      </div>
      <button class="modal-close" (click)="closeModal()">✕</button>
    </div>

    <div class="modal-body">

      <!-- Focus Score -->
      <div class="m-field">
        <label class="m-label">Focus Score <span class="m-req">*</span></label>
        <div class="star-row">
          <button class="star-btn" *ngFor="let n of [1,2,3,4,5]"
            [class.star-active]="n <= focusScore"
            (click)="focusScore = n" type="button">★</button>
          <span class="star-hint">{{ focusScore }}/5</span>
        </div>
      </div>

      <!-- Distraction Count -->
      <div class="m-field">
        <label class="m-label">Distraction Count</label>
        <div class="counter-row">
          <button class="counter-btn" (click)="distractionCount = distractionCount > 0 ? distractionCount - 1 : 0" type="button">−</button>
          <span class="counter-val">{{ distractionCount }}</span>
          <button class="counter-btn" (click)="distractionCount = distractionCount + 1" type="button">+</button>
        </div>
      </div>

      <p class="modal-err" *ngIf="modalError">{{ modalError }}</p>
    </div>

    <div class="modal-footer">
      <button class="btn-cancel" (click)="closeModal()" [disabled]="modalLoading">Cancel</button>
      <button class="btn-confirm" (click)="submitComplete()" [disabled]="modalLoading">
        <span class="spinner" *ngIf="modalLoading"></span>
        <span>{{ modalLoading ? 'Saving...' : 'Submit' }}</span>
      </button>
    </div>

  </div>
</div>

<!-- Page -->
<div class="page">

  <!-- Header -->
  <div class="page-header">
    <div>
      <h1 class="page-title">Task Tracker</h1>
      <p class="page-sub">Manage, start, and complete your tasks</p>
    </div>
    <a routerLink="/tasks/create" class="btn-new">+ New Task</a>
  </div>

  <!-- Filter Tabs -->
  <div class="filter-tabs">
    <button class="tab" [class.tab-active]="filter==='All'"         (click)="filter='All'">All <span class="tab-count">{{ counts.all }}</span></button>
    <button class="tab" [class.tab-active]="filter==='Pending'"     (click)="filter='Pending'">Pending <span class="tab-count">{{ counts.pending }}</span></button>
    <button class="tab" [class.tab-active]="filter==='In Progress'" (click)="filter='In Progress'">In Progress <span class="tab-count">{{ counts.inProgress }}</span></button>
    <button class="tab" [class.tab-active]="filter==='Completed'"   (click)="filter='Completed'">Completed <span class="tab-count">{{ counts.completed }}</span></button>
  </div>

  <!-- Loading skeleton -->
  <div class="skeleton-list" *ngIf="pageLoading">
    <div class="skeleton-card" *ngFor="let i of [1,2,3]"></div>
  </div>

  <!-- Empty state -->
  <div class="empty" *ngIf="!pageLoading && filteredTasks.length === 0">
    <span class="empty-icon">📭</span>
    <p>No tasks found</p>
    <a routerLink="/tasks/create" class="btn-new" style="margin-top:12px">Create your first task</a>
  </div>

  <!-- Task Cards -->
  <div class="task-list" *ngIf="!pageLoading">
    <div class="task-card"
      *ngFor="let task of filteredTasks"
      [class.card-progress]="task.status === 'In Progress'"
      [class.card-done]="task.status === 'Completed'">

      <!-- Left: info -->
      <div class="card-left">

        <div class="card-top">
          <span class="task-title">{{ task.title }}</span>
          <span class="priority-badge" [class]="priorityClass(task.priority)">{{ task.priority }}</span>
        </div>

        <div class="card-meta">
          <span class="meta-chip">📁 {{ task.category }}</span>
          <span class="meta-chip">⏱ {{ task.estimated_time }} min</span>
          <span class="meta-chip" *ngIf="task.due_date && task.due_date !== 'None'">📅 {{ task.due_date | date:'MMM d' }}</span>
        </div>

        <!-- Live timer -->
        <div class="live-timer" *ngIf="task.status === 'In Progress'">
          <span class="timer-dot"></span>
          <span class="timer-text">{{ formatElapsed(task._elapsed) }} elapsed</span>
        </div>

      </div>

      <!-- Right: status + actions -->
      <div class="card-right">

        <span class="status-badge" [class]="statusClass(task.status)">{{ task.status }}</span>

        <div class="card-actions">

          <!-- Start -->
          <button class="btn-start"
            *ngIf="task.status === 'Pending'"
            [disabled]="task._loading"
            (click)="startTask(task)">
            <span class="spinner-sm" *ngIf="task._loading"></span>
            <span *ngIf="!task._loading">▶ Start</span>
          </button>

          <!-- Complete -->
          <button class="btn-complete"
            *ngIf="task.status === 'In Progress'"
            [disabled]="task._loading"
            (click)="openModal(task)">
            ✅ Complete
          </button>

          <!-- Done label -->
          <span class="done-label" *ngIf="task.status === 'Completed'">🎉 Done</span>

        </div>

      </div>

    </div>
  </div>

</div>
